7	/// The one file a skill directory must hold.
8	///
9	/// The directory is the skill, the way https://agentskills.io/specification defines it:
10	/// everything else in it -- `scripts/`, `references/`, `assets/` -- belongs to the
11	/// instructions and is never a definition of its own. A bare `.md` per skill carried
12	/// prose and nothing beside it, so a procedure with a script behind it had to spell that
13	/// script's path as prose and hope the two stayed in step.
14	const SKILL_FILE: &str = "SKILL.md";
