20	pub fn load(root: &Path) -> Result<SkillCatalog> {
21	    let root = root
22	        .canonicalize()
23	        .with_context(|| format!("Failed to resolve skills directory: {:?}", root))?;
24	    if !root.is_dir() {
25	        anyhow::bail!("Skills path is not a directory: {:?}", root);
26	    }
27	
28	    let mut paths = Vec::new();
29	    collect_skill_files(&root, &mut paths)?;
30	    paths.sort();
31	
32	    let mut skills = Vec::new();
33	    for path in paths {
34	        let skill = parse_skill(&path)?;
35	        skills.push(skill);
36	    }
37	    SkillCatalog::new(skills)
