48	/// Find every `SKILL.md` under `directory`, descending only where there is none.
49	///
50	/// A directory holding a `SKILL.md` is a skill, so its children are its resources and
51	/// are not searched for further skills -- one skill cannot nest inside another. Every
52	/// directory above one of them is a category, which the layout uses to group skills and
53	/// the spec says nothing about.
54	fn collect_skill_files(directory: &Path, paths: &mut Vec<PathBuf>) -> Result<()> {
55	    for entry in fs::read_dir(directory)
56	        .with_context(|| format!("Failed to read skills directory: {:?}", directory))?
57	    {
58	        let entry = entry?;
59	        let file_type = entry.file_type()?;
60	        let path = entry.path();
61	        if file_type.is_symlink() {
62	            anyhow::bail!("Skill catalog does not allow symbolic links: {:?}", path);
63	        }
64	        if !file_type.is_dir() {
65	            // Loose files are ignored rather than refused. A skill directory is a
66	            // package, and a stray note or script beside the categories is not a claim
67	            // to be one.
68	            continue;
69	        }
70	        let definition = path.join(SKILL_FILE);
71	        match fs::symlink_metadata(&definition) {
72	            Ok(metadata) if metadata.file_type().is_symlink() => {
73	                anyhow::bail!(
74	                    "Skill catalog does not allow symbolic links: {:?}",
75	                    definition
76	                );
77	            }
78	            Ok(metadata) if metadata.is_file() => paths.push(definition),
79	            _ => collect_skill_files(&path, paths)?,
80	        }
81	    }
82	    Ok(())
83	}
