85	fn parse_skill(path: &Path) -> Result<Skill> {
86	    let raw = fs::read_to_string(path)
87	        .with_context(|| format!("Failed to read skill definition: {:?}", path))?;
88	    let content = raw.trim_start();
89	    if !content.starts_with("---") {
90	        anyhow::bail!("Skill definition must start with `---`: {:?}", path);
91	    }
92	
93	    let rest = &content[3..];
94	    let (end, delimiter_len) = if let Some(pos) = rest.find("\r\n---") {
95	        (pos, 5)
96	    } else if let Some(pos) = rest.find("\n---") {
97	        (pos, 4)
98	    } else {
99	        anyhow::bail!("Could not find closing `---` in skill: {:?}", path);
100	    };
101	
102	    let metadata: SkillMetadata = serde_yaml::from_str(&rest[..end])
103	        .with_context(|| format!("Failed to parse skill frontmatter: {:?}", path))?;
104	    validate_name(path, &metadata.name)?;
105	    validate_description(path, &metadata.description)?;
106	
107	    let instructions = content[3 + end + delimiter_len..].trim().to_string();
108	    if instructions.is_empty() {
109	        anyhow::bail!("Skill instructions must not be empty: {:?}", path);
110	    }
111	
112	    Ok(Skill {
113	        metadata,
114	        instructions,
115	    })
116	}
