118	/// The spec's rules for a skill name, each refused with the file and the rule it broke.
119	///
120	/// A name is what an agent types into `load_skill` and what a directory is called, so
121	/// the two agree by construction: the directory name is the name, and a `name` field
122	/// that says otherwise would be a skill reachable under a word nothing on disk holds.
123	fn validate_name(path: &Path, name: &str) -> Result<()> {
124	    if name.is_empty() {
125	        anyhow::bail!("Skill name must not be empty: {:?}", path);
126	    }
127	    if name.chars().count() > MAX_NAME_CHARS {
128	        anyhow::bail!(
129	            "Skill name '{}' is {} characters; the limit is {MAX_NAME_CHARS}: {:?}",
130	            name,
131	            name.chars().count(),
132	            path
133	        );
134	    }
135	    if !name
136	        .chars()
137	        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
138	    {
139	        anyhow::bail!(
140	            "Skill name '{}' may hold only lowercase letters, digits and hyphens: {:?}",
141	            name,
142	            path
143	        );
144	    }
145	    if name.starts_with('-') || name.ends_with('-') {
146	        anyhow::bail!(
147	            "Skill name '{}' must not start or end with a hyphen: {:?}",
148	            name,
149	            path
150	        );
151	    }
152	    if name.contains("--") {
153	        anyhow::bail!(
154	            "Skill name '{}' must not hold two hyphens in a row: {:?}",
155	            name,
156	            path
157	        );
158	    }
159	    let directory = path
160	        .parent()
161	        .and_then(Path::file_name)
162	        .and_then(|d| d.to_str());
163	    if directory != Some(name) {
164	        anyhow::bail!(
165	            "Skill name '{}' must be the directory it lives in, which is '{}': {:?}",
166	            name,
167	            directory.unwrap_or_default(),
168	            path
169	        );
170	    }
171	    Ok(())
172	}
