1	use serde::Deserialize;
2	use std::collections::BTreeMap;
3	
4	/// The name of the built-in tool that loads a skill.
5	///
6	/// Here rather than in `application`, because the system prompt names it too and
7	/// `infra::template` cannot reach an application constant without inverting the
8	/// dependency. It was a literal in that template, so renaming this would have told every
9	/// model, in every prompt, to call a tool that no longer exists -- and it would have
10	/// called it, received "Unknown tool", and loaded no skill, with nothing failing at
11	/// build time. A rename is therefore a pairing, not a release: the template teaching
12	/// this name and the core dispatching it ship together.
13	///
14	/// A tool the core owns is named the way models say it. There is no namespace in front
15	/// of it: the `server__` prefix that MCP tools carry exists to keep one server's tools
16	/// from colliding with another's, and a built-in has no server to collide with.
17	pub const LOAD_SKILL_TOOL: &str = "load_skill";
18	
19	/// The name of that tool's one argument.
20	///
21	/// Here rather than in `application` for the same reason as the tool name above, and
22	/// shared for a sharper one: it is spelled in two places that cannot see each other --
23	/// the schema `application::tools` declares, and the corrected call
24	/// [`skill_called_as_tool_message`] writes out for a model to copy. They drifted. The
25	/// message went on teaching `{"name": ...}` after the schema became `skill_name` and
26	/// every other spelling stopped being accepted, so following the message exactly was a
27	/// refusal.
28	///
29	/// Nothing caught it: the argument key is a JSON string built on one side and a JSON
30	/// string built on the other, and the tests below assert the message names the tool and
31	/// the skill, never the key. One constant is what makes the two agree.
32	pub const LOAD_SKILL_ARGUMENT: &str = "skill_name";
33	
34	/// What to say when a tool call names a skill instead of a tool.
35	///
36	/// A reviewer called a skill as a tool and was told only "Invalid tool name format
37	/// (expected server__tool)". It did not call the loader afterwards -- it reported to the
38	/// pull request that it HAD run the skill, which was read by a person.
39	///
40	/// It reached for that name because the prompt hands it one: skills are listed as
41	/// ``- `environment`: ...`` backticked, in the same shape a tool name takes, and a model
42	/// that had only the name could not tell the two apart. This is the message for when the
43	/// confusion happens anyway, and it names the call that works rather than the rule that
44	/// was broken -- measured three times in this project as the difference between a
45	/// refusal that is followed and one that is not.
46	///
47	/// The [`SkillCatalog`] holds the names, so the caller asks it first and only formats
48	/// here: what a skill is called is a fact about the catalog, not about the shape of a
49	/// string.
50	pub fn skill_called_as_tool_message(name: &str) -> String {
51	    format!(
52	        "'{name}' is a skill, not a tool. A skill is loaded, not called: use {LOAD_SKILL_TOOL} \
53	         with {{\"{LOAD_SKILL_ARGUMENT}\": \"{name}\"}}, then follow what it returns. \
54	         Nothing has run yet."
55	    )
56	}
57	
58	/// Metadata exposed in the system prompt before a skill is loaded.
59	#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
60	pub struct SkillMetadata {
61	    pub name: String,
62	    pub description: String,
63	}
64	
65	/// A validated skill available to the current run.
66	#[derive(Debug, Clone, PartialEq, Eq)]
67	pub struct Skill {
68	    pub metadata: SkillMetadata,
69	    pub instructions: String,
70	}
71	
72	/// Immutable, name-indexed set of skills validated at run startup.
73	#[derive(Debug, Clone, Default)]
74	pub struct SkillCatalog {
75	    skills: BTreeMap<String, Skill>,
76	}
77	
78	impl SkillCatalog {
79	    pub fn new(skills: Vec<Skill>) -> anyhow::Result<Self> {
80	        let mut indexed = BTreeMap::new();
81	        for skill in skills {
82	            let name = skill.metadata.name.clone();
83	            if indexed.insert(name.clone(), skill).is_some() {
84	                anyhow::bail!("Duplicate skill name '{}'", name);
85	            }
86	        }
87	        Ok(Self { skills: indexed })
88	    }
89	
90	    pub fn metadata(&self) -> Vec<SkillMetadata> {
91	        self.skills
92	            .values()
93	            .map(|skill| skill.metadata.clone())
94	            .collect()
95	    }
96	
97	    pub fn get(&self, name: &str) -> Option<&Skill> {
98	        self.skills.get(name)
99	    }
100	}
101	
102	#[cfg(test)]
103	mod skill_called_as_tool_tests {
104	    use super::{skill_called_as_tool_message, LOAD_SKILL_ARGUMENT, LOAD_SKILL_TOOL};
105	
106	    /// The property is that the message names the call that works. A reviewer that saw
107	    /// only "expected server__tool" went on to tell a pull request it had run the skill.
108	    #[test]
109	    fn a_skill_name_is_told_which_tool_loads_it() {
110	        let message = skill_called_as_tool_message("environment");
111	        assert!(message.contains(LOAD_SKILL_TOOL));
112	        assert!(message.contains("environment"));
113	    }
114	
115	    /// The corrected call is one a model copies verbatim, so the argument's name has to
116	    /// be the one the tool takes.
117	    ///
118	    /// It was not. This message went on writing `{"name": ...}` after the schema became
119	    /// `skill_name` and every other spelling stopped being accepted, which made following
120	    /// it exactly a refusal. Nothing caught it: the key was a JSON string built here and
121	    /// a JSON string built in `application::tools`, and the assertions above name the
122	    /// tool and the skill but never the key.
123	    #[test]
124	    fn the_corrected_call_names_the_argument_the_tool_takes() {
125	        let message = skill_called_as_tool_message("tdd");
126	        assert!(
127	            message.contains(&format!(r#"{{"{LOAD_SKILL_ARGUMENT}": "tdd"}}"#)),
128	            "{message}"
129	        );
130	    }
131	
132	    /// It has to say that nothing happened, because the failure this came from was an
133	    /// agent reporting the skill as having run.
134	    #[test]
135	    fn the_message_says_nothing_has_run() {
136	        let message = skill_called_as_tool_message("on-demand-audit");
137	        assert!(message.to_lowercase().contains("nothing has run"));
138	    }
139	}

